package com.mohistmc.academy.network;
import com.mohistmc.academy.AcademyCraft;import io.netty.buffer.ByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.ResourceLocation;import net.neoforged.neoforge.network.handling.IPayloadContext;
public record FlashingStatePacket(boolean active,long epoch)implements CustomPacketPayload{public static final Type<FlashingStatePacket>TYPE=new Type<>(ResourceLocation.fromNamespaceAndPath(AcademyCraft.MODID,"flashing_state"));public static final StreamCodec<ByteBuf,FlashingStatePacket>STREAM_CODEC=StreamCodec.ofMember((p,b)->{b.writeBoolean(p.active);b.writeLong(p.epoch);},b->new FlashingStatePacket(b.readBoolean(),b.readLong()));public Type<? extends CustomPacketPayload>type(){return TYPE;}public static void handle(FlashingStatePacket p,IPayloadContext c){c.enqueueWork(()->com.mohistmc.academy.client.ClientPacketBridge.flashing(p));}}
